insert into public.reference_photos (categoria, tipo_peca, pose, data_comemorativa, nome_referencia, prompt_mestre, perfis_sugeridos, aspecto, ordem, status) values ('evergreen', 'Peças em Você', 'Apoiada em Cadeira — Pulseira', NULL, 'voce_09_apoiada-em-cadeira', 'Serão anexadas duas fotografias: a FOTO 1, com o rosto da própria assinante, e a FOTO 2, com a(s) joia(s) do produto. A FOTO 1 determina exclusivamente a identidade da modelo: preserve fielmente formato do rosto, olhos, sobrancelhas, nariz, boca, mandíbula, proporções faciais, tom de pele e cabelo (cor, comprimento e textura reais) — a pessoa da imagem final deve continuar claramente reconhecível como a mesma pessoa da FOTO 1. Não a transforme em um rosto genérico, não rejuvenesça, não altere suas feições ou idade aparente. A FOTO 2 determina exclusivamente as joias: identifique exatamente quantas peças e de que tipo existem nela e utilize somente essas peças, na mesma quantidade — nunca invente, duplique, remova ou substitua nenhuma peça; preserve formato, proporções, espessura, acabamento, brilho, cor do metal, pedras e todos os detalhes originais. Se a FOTO 2 contiver outra pessoa, ignore completamente essa pessoa — rosto, corpo, pele, cabelo, roupa e pose não servem de referência, apenas as joias. Nunca misture as duas fotos: cabelo e tom de pele vêm sempre da FOTO 1; joias vêm sempre da FOTO 2. Se determinado tipo de joia não existir na FOTO 2, ele não deve aparecer na imagem final sob nenhuma hipótese.
